// workItemOriginModelOpinion is stamped into EVERY finding's base spec by
// classifyFinding, whatever mode files it. It exists for one reader:
// detected-item-promoter's origin door (bugs_open/405, migration 629). Every
// prior door in that promoter interrogates the HANDLER and the (item_type,
// handler) pair's history; none asks what PRODUCED the row — so LLM-audit
// opinions rode a known-good door whose completions were earned by mechanical
// defects (27 promoted 08-20→24 while the sweep was off). The 391 lane measured
// that this axis cannot be DERIVED from any existing column (created_by is a
// drifting name list; source='discovery' spans 27 creators; spec?audit_source
// over-blocks tool-acceptance-tier4) — so it is WRITTEN, here, at the one seam
// every model-seat finding passes through.
//
// Stamped unconditionally rather than per-mode: today every caller of this
// action is a model seat (6 live write steps, 0 mechanical), and if a
// mechanical producer ever adopts the action, the stamp widens the promoter's
// HOLD — the safe direction (held for a person, not dispatched by mistake).
// The literal must match migration 629's door verbatim; the lockstep test
// (write_audit_findings_origin_test.go) reads the migration file and fails the
// build if the two ever disagree.
const workItemOriginModelOpinion = "model_opinion"

// parse

	spec := map[string]interface{}{
		"audit_source":    auditSource,
		"category":        f.Category,
		"description":     f.Description,
		"original_domain": "build",
		// The provenance stamp the promoter's origin door reads — see the
		// workItemOriginModelOpinion const for the whole story (bugs_open/405).
		"origin": workItemOriginModelOpinion,
	}

)

func TestOriginStamp_EveryClassificationArmCarriesIt(t *testing.T) {
	siteID := uuid.New()
	pageID := uuid.New()
	pages := map[string]pageInfo{"about": {ID: pageID, Name: "about"}}
	for name, f := range map[string]auditFinding{
		"routed content arm (content_rewrite)": {Category: "content", Page: "about", Description: "x", Severity: "medium"},
		"design arm (needs_design_review)":     {Category: "colour", Page: "about", Description: "x", Severity: "low"},
		"no-handler arm (capability_gap)":      {Category: "cta", Page: "about", Description: "x", Severity: "low"},
		"unknown-category fallback":            {Category: "zzz_never_a_category", Page: "about", Description: "x", Severity: "low"},
	} {
		c := classifyFinding(f, pages, siteID, "site-review")
		if got := c.Spec["origin"]; got != workItemOriginModelOpinion {
			t.Errorf("%s: spec.origin = %v, want %q — an arm without the stamp is a row the promoter's origin door cannot see", name, got, workItemOriginModelOpinion)
		}
	}
}

func TestOriginStamp_SurvivesRecordMode(t *testing.T) {
	pageID := uuid.New()
	c := classifyFinding(auditFinding{Category: "content", Page: "about", Description: "x", Severity: "medium"},
		map[string]pageInfo{"about": {ID: pageID, Name: "about"}}, uuid.New(), "offer-analysis")
	out := recordOnlyFinding(c, "offer-analysis")
	if out.Spec["origin"] != workItemOriginModelOpinion {
		t.Fatalf("record mode dropped the origin stamp: %v", out.Spec)
	}
}

// TestOriginDoorLockstep reads migration 629 and fails if the SQL door and the
// Go stamp disagree — the Go↔SQL drift 405 §7 names as where candidate 1 breaks.
// The migration file is committed for ever, so a missing file is a FAILURE
// (vacuity guard), not a skip.
func TestOriginDoorLockstep(t *testing.T) {
	const migration = "../../../docs/agent_docs/sql_for_agents/629_promoter_origin_door_holds_model_opinions.sql"
	raw, err := os.ReadFile(migration)
	if err != nil {
		t.Fatalf("lockstep half missing: %v — if the migration was renamed, this test's path is the other copy of that fact", err)
	}
	sql := string(raw)
	// The full predicate, built FROM the Go constant so a drifted stamp cannot
	// match. It must appear exactly twice: once in the edit's replacement text
	// and once in the verify block's verbatim assertion — the two sites that

DO $edit$
DECLARE
    v_q  text;
    a1   text := $a$               ) AS floor_ok
        FROM site_work_items wi$a$;
    r1   text := $a$               ) AS floor_ok,
               -- DOOR-CLOSER 3 (bugs_open/405, migration 629): PROVENANCE. Every other
               -- door interrogates the handler and the pair's history; none asked what
               -- PRODUCED the row, so LLM-audit opinions rode a door whose completions
               -- were earned by mechanical defects (27 promoted 08-20..24 with the
               -- sweep off). The stamp is written by write_audit_findings itself
               -- (workItemOriginModelOpinion - lockstep-pinned to this literal); a row
               -- carrying it is a JUDGEMENT: held for a person or record-mode's
               -- release recipe, never promoted by competence history.
               (COALESCE(wi.spec->>'origin', '') <> 'model_opinion') AS origin_ok
        FROM site_work_items wi$a$;
    a2   text := $a$        WHERE pipe_ok AND handler_ok AND known_good AND floor_ok
        ORDER BY created_at ASC$a$;
    r2   text := $a$        WHERE pipe_ok AND handler_ok AND known_good AND floor_ok AND origin_ok
        ORDER BY created_at ASC$a$;
    a3   text := $a$        WHERE NOT (pipe_ok AND handler_ok AND known_good AND floor_ok)$a$;
    r3   text := $a$        WHERE NOT (pipe_ok AND handler_ok AND known_good AND floor_ok AND origin_ok)$a$;
    a4   text := $a$               CASE WHEN NOT handler_ok  THEN 'handler not a live agent'$a$;
    r4   text := $a$               CASE WHEN NOT handler_ok  THEN 'handler not a live agent'
                    WHEN NOT origin_ok   THEN 'model opinion - release by hand or via record mode (bugs_open/405)'$a$;
BEGIN
    SELECT pre_query INTO v_q FROM scheduled_tasks WHERE name = 'detected-item-promoter';
    IF v_q IS NULL THEN RAISE EXCEPTION '405/629: detected-item-promoter not found'; END IF;

    IF (length(v_q) - length(replace(v_q, a1, ''))) / length(a1) <> 1 THEN RAISE EXCEPTION '405/629 drift: anchor 1 (scored floor_ok) not exactly once'; END IF;
    IF (length(v_q) - length(replace(v_q, a2, ''))) / length(a2) <> 1 THEN RAISE EXCEPTION '405/629 drift: anchor 2 (candidates) not exactly once'; END IF;
    IF (length(v_q) - length(replace(v_q, a3, ''))) / length(a3) <> 1 THEN RAISE EXCEPTION '405/629 drift: anchor 3 (held complement) not exactly once'; END IF;
    IF (length(v_q) - length(replace(v_q, a4, ''))) / length(a4) <> 1 THEN RAISE EXCEPTION '405/629 drift: anchor 4 (held CASE) not exactly once'; END IF;

    v_q := replace(v_q, a1, r1);
    v_q := replace(v_q, a2, r2);
    v_q := replace(v_q, a3, r3);
    v_q := replace(v_q, a4, r4);

    UPDATE scheduled_tasks
       SET pre_query = v_q,
           description = description || ' Door 5 (bugs_open/405, mig 629): rows stamped spec.origin=''model_opinion'' are HELD, never promoted - the stamp is written by write_audit_findings and read here.',
           updated_at = now()
     WHERE name = 'detected-item-promoter';
    RAISE NOTICE '405/629: origin door installed';
END $edit$;
